def factorial(n: int) -> int:
    # Base case
    if n <= 1:
        return 1
    # Recursive case
    return n * factorial(n - 1)

print(factorial(5))
print(factorial(1))

import sys

def count_depth(n, current_depth=1):
    if current_depth >= 5:
        return f"Reached base case at depth {current_depth}"
    return count_depth(n, current_depth + 1)

print(f"Default Python recursion limit: {sys.getrecursionlimit()}")
print(count_depth(10))

from functools import lru_cache

# Memoized Fibonacci using Python lru_cache
@lru_cache(maxsize=None)
def fibonacci_memo(n: int) -> int:
    if n <= 1:
        return n
    return fibonacci_memo(n - 1) + fibonacci_memo(n - 2)

print(fibonacci_memo(10))
print(fibonacci_memo(50))
